const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xfff4e5, 1.45);
keyLight.position.set(8, 12, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xcce0ff, 0.65);
fillLight.position.set(-8, 6, 4);

const rimLight = new THREE.PointLight(0x88ccff, 0.85, 25);
rimLight.position.set(-6, 4, -8);

const warmRim = new THREE.PointLight(0xffaa77, 0.45, 20);
warmRim.position.set(6, 2, -6);

scene.add(new THREE.AmbientLight(0x7a8aa6, 0.35), keyLight, fillLight, rimLight, warmRim);

const floorGeo = new THREE.CircleGeometry(12, 128);
const floorMat = new THREE.MeshStandardMaterial({ 
  color: 0xe8eef5, 
  roughness: 0.85, 
  metalness: 0.05 
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -2;
floor.receiveShadow = true;
scene.add(floor);

const heroGroup = new THREE.Group();
scene.add(heroGroup);

const coreGeo = new THREE.IcosahedronGeometry(1.2, 0);
const coreMat = new THREE.MeshPhysicalMaterial({
  color: 0x2a3b55,
  metalness: 0.1,
  roughness: 0.15,
  transmission: 0.6,
  thickness: 1.5,
  clearcoat: 1.0,
  clearcoatRoughness: 0.1,
  ior: 1.5
});
const core = new THREE.Mesh(coreGeo, coreMat);
core.castShadow = true;
heroGroup.add(core);

const ring1Geo = new THREE.TorusGeometry(2.2, 0.08, 16, 100);
const ring1Mat = new THREE.MeshStandardMaterial({ 
  color: 0xffb366, 
  metalness: 0.9, 
  roughness: 0.2 
});
const ring1 = new THREE.Mesh(ring1Geo, ring1Mat);
ring1.rotation.x = Math.PI / 2;
ring1.castShadow = true;
heroGroup.add(ring1);

const ring2Geo = new THREE.TorusGeometry(3.0, 0.05, 16, 100);
const ring2Mat = new THREE.MeshStandardMaterial({ 
  color: 0x6699ff, 
  metalness: 0.8, 
  roughness: 0.3 
});
const ring2 = new THREE.Mesh(ring2Geo, ring2Mat);
ring2.rotation.x = Math.PI / 3;
ring2.rotation.y = Math.PI / 6;
ring2.castShadow = true;
heroGroup.add(ring2);

const satellites = [];
const satGeo = new THREE.SphereGeometry(0.25, 32, 32);
const satMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  metalness: 0.0,
  roughness: 0.0,
  transmission: 0.95,
  thickness: 0.5
});

for (let i = 0; i < 3; i++) {
  const sat = new THREE.Mesh(satGeo, satMat);
  const pivot = new THREE.Group();
  pivot.rotation.y = (i / 3) * Math.PI * 2;
  pivot.rotation.x = Math.random() * 0.5;
  sat.position.set(2.8, 0, 0);
  pivot.add(sat);
  heroGroup.add(pivot);
  satellites.push({ mesh: sat, pivot: pivot, speed: 0.5 + i * 0.2, offset: i * 2.0 });
}

const particleCount = 60;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const phases = new Float32Array(particleCount);

for (let i = 0; i < particleCount; i++) {
  const r = 4 + Math.random() * 3;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.random() * Math.PI;
  positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  positions[i * 3 + 1] = r * Math.cos(phi) * 0.5;
  positions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
  phases[i] = Math.random() * Math.PI * 2;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
particleGeo.setAttribute('phase', new THREE.BufferAttribute(phases, 1));

const particleMat = new THREE.PointsMaterial({
  color: 0x88aaff,
  size: 0.08,
  transparent: true,
  opacity: 0.6,
  blending: THREE.AdditiveBlending
});

const particles = new THREE.Points(particleGeo, particleMat);
heroGroup.add(particles);

camera.position.set(6, 4, 8);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.autoRotate = false;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  heroGroup.rotation.y = t * 0.15;
  heroGroup.position.y = Math.sin(t * 0.5) * 0.3;

  core.rotation.x = t * 0.2;
  core.rotation.z = t * 0.1;

  ring1.rotation.x = (Math.PI / 2) + Math.sin(t * 0.3) * 0.1;
  ring1.rotation.y = t * 0.4;

  ring2.rotation.x = (Math.PI / 3) + Math.cos(t * 0.25) * 0.15;
  ring2.rotation.y = (Math.PI / 6) + t * 0.25;

  satellites.forEach((sat, i) => {
    sat.pivot.rotation.y = t * sat.speed + sat.offset;
    sat.mesh.position.y = Math.sin(t * 2 + sat.offset) * 0.3;
  });

  const posAttr = particleGeo.attributes.position;
  for (let i = 0; i < particleCount; i++) {
    const phase = particleGeo.attributes.phase.getX(i);
    const y = posAttr.getY(i);
    posAttr.setY(i, y + Math.sin(t + phase) * 0.005);
  }
  posAttr.needsUpdate = true;
  particles.rotation.y = t * 0.05;

  rimLight.intensity = 0.75 + Math.sin(t * 1.5) * 0.15;
  warmRim.intensity = 0.45 + Math.cos(t * 1.2) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}

animate();

